from graphlib import TopologicalSorter

def test_disconnected():
    graph = {
        "A": ["B"],
        "B": [],
        "C": ["D"],
        "D": [],
    }
    # B -> A
    # D -> C

    ts = TopologicalSorter(graph)
    order = list(ts.static_order())
    print(f"Order: {order}")

    # Possible orders: [B, A, D, C], [B, D, A, C], [B, D, C, A], [D, C, B, A], [D, B, C, A], [D, B, A, C]
    # Let's just check if the dependencies are respected.

    pos = {node: i for i, node in enumerate(order)}
    if pos["B"] < pos["A"] and pos["D"] < pos["C"]:
        print("Test passed!")
    else:
        print("Test failed!")
        raise Exception(f"Unexpected order: {order}")

if __name__ == "__main__":
    test_disconnected()
